ep_session_script.versaScript:
json_xml import *;
vdb import *;
http import *;
email import *;
crypto import *;
jwt import *;
time import *;
datetime import *;

let req = params;
let body = req.body ?? {};
let authCtx = req.auth ?? {};
let actor = str(authCtx.username ?? authCtx.sub ?? "system").trim();
if (actor == "") {
  actor = "system";
}
let dryRun = body.dryRun == true || req.dryRun == true;
let sessionId = str(body.sessionId ?? req.sessionId ?? "").trim();
let nextState = str(body.state ?? req.state ?? "RUNNING").trim().upper();

let sessions = vdb.collection("sessions");
let rows = [];
if (sessionId != "") {
  let lookup = sessions.find({sessionId: {$eq: sessionId}}, 1);
  rows = lookup.data ?? [];
}
if (leng(rows) == 0) {
  let fallback = sessions.find({}, 1);
  rows = fallback.data ?? [];
}
if (leng(rows) == 0) {
  return {ok: false, statusCode: 404, reason: "No session is available to run"};
}

let session = rows[0];
sessionId = str(session.sessionId ?? sessionId).trim();
let previousState = str(session.state ?? "OPEN").trim().upper();
let payload = type(session.payload) == "object" ? session.payload : {};
let flags = type(payload.flags) == "object" ? payload.flags : {};
let deep = type(flags.deep) == "object" ? flags.deep : {};
let trace = body.trace == true || req.trace == true || deep.trace == true;
let runId = crypto.uuid();
let nowTs = datetime.now().isoformat();
let nextPayload = {
  flags: {
    deep: {
      beta: deep.beta == false ? false : true,
      trace: trace
    }
  },
  lastRun: {
    runId: runId,
    actor: actor,
    at: nowTs,
    previousState: previousState,
    nextState: nextState
  }
};
let updatePayload = {
  state: nextState,
  payload: nextPayload
};

if (dryRun) {
  return {ok: true, dryRun: true, sessionId: sessionId, previousState: previousState, nextState: nextState, update: updatePayload};
}

let updateRes = sessions.update({sessionId: {$eq: sessionId}}, updatePayload);
if (updateRes.ok == false) {
  return {ok: false, statusCode: 500, reason: updateRes.error ?? "Failed to persist session run state", sessionId: sessionId, result: updateRes};
}

let runs = vdb.collection("session_runs");
let runRes = runs.insert({
  runId: runId,
  sessionId: sessionId,
  actor: actor,
  previousState: previousState,
  nextState: nextState,
  createdAt: nowTs
});

return {ok: true, sessionId: sessionId, previousState: previousState, nextState: nextState, runId: runId, updated: true, runRecorded: runRes.ok ?? false};

